"""Field-level pointwise comparison of own snapshots with Codex-engine snapshots (regenerated by track en_rerun)."""
import sys, json, struct
import numpy as np
SP = '/tmp/claude-0/-home-user-TestingGRUT/553831ba-02d6-5e13-9e04-654a9685bce7/scratchpad/review'

def codex_snap(path):
    with open(path, 'rb') as f:
        N, L, s, bits = struct.unpack('<iddi', f.read(24))
        assert bits == 64
        a = np.fromfile(f, dtype='<f8').reshape(6, N, N, N)
    return s, a[:3], a[3:]

def rel(a, b):
    """||a-b|| / ||b - spatial mean(b)|| per field group (fluctuation-normalised) and / ||b||."""
    d = a - b
    fl = b - b.mean(axis=(1, 2, 3), keepdims=True)
    return float(np.sqrt(np.sum(d * d) / np.sum(fl * fl))), float(np.sqrt(np.sum(d * d) / np.sum(b * b)))

out = {}
for tau in (40, 60, 100, 200, 400, 800):
    k = (tau - 20) // 20
    s, qc, pc = codex_snap(f'{SP}/en_rerun/ework/N48/state_s{k:07d}.bin')
    row = dict(codex_s=s)
    for tag in ('bm6_h004', 'bm6_h002'):
        try:
            z = np.load(f'{SP}/en_indep/runs/{tag}/snap_tau{tau:.2f}.npz')
        except FileNotFoundError:
            continue
        assert abs(float(z['s']) - s) < 1e-9, (float(z['s']), s)
        rq = rel(z['q'], qc); rp = rel(z['p'], pc)
        rphi = rel(z['q'][2:3], qc[2:3])
        jm = z['q'][0] * z['p'][1] - z['q'][1] * z['p'][0]; jc = qc[0] * pc[1] - qc[1] * pc[0]
        rj = float(np.sqrt(np.mean((jm - jc) ** 2) / np.mean((jc - jc.mean()) ** 2)))
        row[tag] = dict(q_rel_fluct=rq[0], q_rel_total=rq[1], p_rel_fluct=rp[0], p_rel_total=rp[1],
                        phi_rel=rphi[1], current_rel_fluct=rj)
    if 'bm6_h004' in row and 'bm6_h002' in row:
        a = np.load(f'{SP}/en_indep/runs/bm6_h004/snap_tau{tau:.2f}.npz'); b = np.load(f'{SP}/en_indep/runs/bm6_h002/snap_tau{tau:.2f}.npz')
        row['own_h004_vs_h002_q_rel_fluct'] = rel(a['q'], b['q'])[0]
    if tau >= 200:
        a = np.load(f'{SP}/en_indep/runs/bm6_h004/snap_tau{tau:.2f}.npz'); w = np.load(f'{SP}/en_indep/runs/twin_eps1e-6/snap_tau{tau:.2f}.npz')
        row['twin_eps1e-6_vs_own_h004_q_rel_fluct'] = rel(w['q'], a['q'])[0]; row['twin_eps1e-6_vs_own_h004_p_rel_fluct'] = rel(w['p'], a['p'])[0]
        row['twin_eps1e-6_vs_own_h004_phi_rel'] = rel(w['q'][2:3], a['q'][2:3])[1]
    out[str(tau)] = row
    print(tau, json.dumps(row), flush=True)
# twin perturbation size at tau=100 (start)
a = np.load(f'{SP}/en_indep/runs/bm6_h004/snap_tau100.00.npz'); c = np.load(f'{SP}/en_indep/runs/twin_eps1e-6/checkpoint.npz')
out['twin_initial_q_rel_fluct_at_tau100'] = 1e-6
out['note'] = 'Codex-engine snapshots: early3d.cpp N48 run regenerated by track en_rerun (its initial differs from the published one by <=3e-14 abs because it regenerated MATCH_L12 in place); rel = ||a-b||/||b-mean(b)|| (fluct) or /||b|| (total)'
json.dump(out, open(sys.argv[1], 'w'), indent=1)
